/* eslint-disable */
/**
 * DEMO data seeder — fills an EMPTY demo database with a fictional logistics company, customers, carriers,
 * staff, rate cards, ~1,500 shipments over two months (with scans, PODs and statuses), pickups, invoices
 * (generated by the real billing engine), payments, vendor bills and expenses. No real names anywhere.
 *
 * Run from apps/api after `npm run build`, against the DEMO database only:
 *   node scripts/demo/seed-demo.js
 * Refuses to run unless DATABASE_URL's database name contains "demo".
 */
const path = require('path');
const db = String(process.env.DATABASE_URL || '');
const dbName = (db.match(/\/([^/?]+)(\?|$)/) || [])[1] || '';
if (!/demo/i.test(dbName)) { console.error(`Refusing: database "${dbName}" is not a demo database.`); process.exit(1); }

const { NestFactory } = require('@nestjs/core');
const { AppModule } = require(path.join(__dirname, '../../dist/app.module'));
const { PrismaService } = require(path.join(__dirname, '../../dist/prisma/prisma.service'));
const { ShipmentsService } = require(path.join(__dirname, '../../dist/modules/shipments/shipments.service'));
const { InvoiceService } = require(path.join(__dirname, '../../dist/modules/billing/invoice.service'));
const { VendorBillsService } = require(path.join(__dirname, '../../dist/modules/vendorbills/vendorbills.service'));
const bcrypt = require('bcryptjs');

// ---------- deterministic randomness ----------
let seed = 20261101;
const rnd = () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
const pick = (a) => a[Math.floor(rnd() * a.length)];
const between = (a, b) => a + rnd() * (b - a);
const int = (a, b) => Math.floor(between(a, b + 1));
const digits = (n) => Array.from({ length: n }, () => int(0, 9)).join('');
const D = (v) => Number(Number(v).toFixed(2));
const DAY = 864e5;

// ---------- the fictional world ----------
const COMPANY = {
  code: 'NWX', name: 'Northwind Express Pvt Ltd',
  attrs: {
    legalName: 'NORTHWIND EXPRESS PRIVATE LIMITED', gstin: '07AAACN1234Q1Z5', stateCode: '07', sacCode: '996812', isDefault: true,
    email: 'accounts@northwind.example', phones: '011-40000000', jurisdiction: 'Delhi',
    addressLines: ['Unit 4, Logistics Park, Sector 7,', 'Dwarka, New Delhi - 110075'],
    bank: { beneficiary: 'NORTHWIND EXPRESS PRIVATE LIMITED', name: 'DEMO BANK', accountNo: '000123456789', ifsc: 'DEMO0001234', branch: 'Dwarka', address: 'Dwarka, New Delhi' },
    invoicePad: 5, invoiceNextNo: 1,
  },
};
const BRANCHES = [['DEL', 'Delhi', 'Delhi'], ['BOM', 'Mumbai', 'Mumbai'], ['BLR', 'Bengaluru', 'Bengaluru']];
const HUBS = [['DEL', 'Delhi Hub', 'NORTH'], ['BOM', 'Mumbai Hub', 'WEST'], ['BLR', 'Bengaluru Hub', 'SOUTH'], ['MAA', 'Chennai Hub', 'SOUTH'], ['HYD', 'Hyderabad Hub', 'SOUTH'], ['CCU', 'Kolkata Hub', 'EAST'], ['AMD', 'Ahmedabad Hub', 'WEST'], ['PNQ', 'Pune Hub', 'WEST']];
const SALES = [['AKS', 'Ananya Kapoor'], ['RVM', 'Rohan Verma'], ['NDS', 'Neha Desai']];
const CARRIERS = [
  { code: 'SKY', name: 'SkyLine Air Express', modes: 'AIR,SURFACE', nets: [['AIR'], ['SURFACE']] },
  { code: 'RDW', name: 'Roadway Cargo', modes: 'SURFACE', nets: [['SURFACE']] },
  { code: 'PJT', name: 'ParcelJet Logistics', modes: 'AIR,SURFACE', nets: [['AIR'], ['SURFACE']] },
  { code: 'MRD', name: 'Meridian Freight', modes: 'SURFACE', nets: [['SURFACE']] },
  { code: 'VTX', name: 'Vertex Express', modes: 'SURFACE', nets: [['SURFACE']] },
];
const CUSTOMERS = [
  ['Saffron Trail Handicrafts Pvt Ltd', 'DEL'], ['Peacock Home Decor LLP', 'DEL'], ['Monsoon Apparels Pvt Ltd', 'BOM'], ['Lotus Pharma Distributors', 'BOM'],
  ['Banyan Electricals Pvt Ltd', 'DEL'], ['Indigo Weaves Textiles', 'BLR'], ['Copperleaf Kitchenware LLP', 'DEL'], ['Marigold Cosmetics Pvt Ltd', 'BOM'],
  ['Riverstone Auto Parts', 'DEL'], ['Sandalwood Organics Pvt Ltd', 'BLR'], ['Tarang Electronics', 'BOM'], ['Kesari Foods Pvt Ltd', 'DEL'],
  ['Neelkanth Steel Traders', 'DEL'], ['Chandni Textiles', 'BOM'], ['Ashoka Office Supplies', 'DEL'], ['Pinewood Furniture Works', 'BLR'],
  ['Sunbeam Solar Systems Pvt Ltd', 'BOM'], ['Bluebird Books & Stationery', 'DEL'], ['Greenfield Agro Products', 'BLR'], ['Silverline Medical Devices', 'BOM'],
  ['Zenith Sports Gear', 'DEL'], ['Orchid Fashion House', 'BOM'], ['Granite Hardware Mart', 'DEL'], ['Coral Toys & Games', 'BLR'], ['Everest Industrial Tools', 'BOM'],
];
const ORIGINS = { DEL: ['110037', '110020', '110075', '122001', '201301'], BOM: ['400072', '400093', '400069', '421302', '400701'], BLR: ['560048', '560100', '560068'] };
const CITY = { DEL: ['New Delhi', 'Delhi'], BOM: ['Mumbai', 'Maharashtra'], BLR: ['Bengaluru', 'Karnataka'] };
const STATE_CODE = { DEL: '07', BOM: '27', BLR: '29' };
const FIRST = ['Aarav', 'Vivaan', 'Aditya', 'Ishaan', 'Kabir', 'Riya', 'Ananya', 'Diya', 'Meera', 'Saanvi', 'Arjun', 'Kavya', 'Rahul', 'Pooja', 'Siddharth', 'Nisha', 'Varun', 'Sneha', 'Manish', 'Priya', 'Karan', 'Tanvi', 'Yash', 'Simran', 'Harsh', 'Aisha', 'Dev', 'Ira', 'Nikhil', 'Zoya'];
const LAST = ['Sharma', 'Verma', 'Iyer', 'Nair', 'Patel', 'Shah', 'Reddy', 'Gupta', 'Mehta', 'Rao', 'Singh', 'Das', 'Joshi', 'Kulkarni', 'Bose', 'Menon', 'Chopra', 'Malhotra', 'Pillai', 'Sinha'];
const STREETS = ['MG Road', 'Station Road', 'Industrial Area Phase 2', 'Sector 18', 'Civil Lines', 'Ring Road', 'Market Yard', 'Gandhi Nagar', 'Nehru Place', 'Link Road', 'Main Bazaar', 'Tech Park Road'];
const GOODS = ['Garments', 'Electronics accessories', 'Books', 'Medicines', 'Auto parts', 'Kitchenware', 'Cosmetics', 'Spare parts', 'Furniture fittings', 'Toys', 'Documents', 'Handicrafts', 'Hardware'];
const PASSWORD = 'Demo@123';

const zoneOf = (z) => String(z || '').replace(/\s+/g, '').toUpperCase();
const region = (z) => zoneOf(z).replace(/\d/g, '');
const NEAR = { N: ['C', 'W'], S: ['W', 'E'], W: ['N', 'S', 'C'], E: ['NE', 'C', 'S'], C: ['N', 'W', 'E'], NE: ['E'] };
const tier = (o, d) => (zoneOf(o) === zoneOf(d) ? 0 : region(o) === region(d) ? 1 : (NEAR[region(o)] || []).includes(region(d)) ? 2 : 3);

(async () => {
  const app = await NestFactory.createApplicationContext(AppModule, { logger: ['error'] });
  const prisma = app.get(PrismaService);
  const shipmentsSvc = app.get(ShipmentsService);
  const invoices = app.get(InvoiceService);
  const vendorBills = app.get(VendorBillsService);
  const log = (...a) => console.log(new Date().toISOString().slice(11, 19), ...a);

  if (await prisma.shipment.count()) { console.error('Demo DB already has shipments — recreate the database before seeding.'); process.exit(1); }

  // ---------- masters ----------
  await prisma.masterEntry.upsert({ where: { type_code: { type: 'COMPANY', code: COMPANY.code } }, update: { name: COMPANY.name, attrs: COMPANY.attrs }, create: { type: 'COMPANY', code: COMPANY.code, name: COMPANY.name, attrs: COMPANY.attrs } });
  for (const [code, name, city] of BRANCHES) await prisma.masterEntry.upsert({ where: { type_code: { type: 'BRANCH', code } }, update: {}, create: { type: 'BRANCH', code, name, attrs: { city } } });
  for (const [code, name] of SALES) await prisma.masterEntry.upsert({ where: { type_code: { type: 'SALES_EXEC', code } }, update: {}, create: { type: 'SALES_EXEC', code, name, attrs: {} } });
  const hubs = {};
  for (const [code, name, zone] of HUBS) hubs[code] = await prisma.hub.upsert({ where: { code }, update: {}, create: { code, name, zone } });
  for (const c of CARRIERS) {
    await prisma.vendor.create({ data: { vendorCode: c.code, name: c.name, modes: c.modes, mode: c.modes.split(',')[0], isActive: true, city: 'New Delhi', state: 'Delhi', contactName: `${pick(FIRST)} ${pick(LAST)}`, contactPhone: `98${digits(8)}`, contactEmail: `ops@${c.code.toLowerCase()}.example`, gstEnabled: true } });
  }
  log('masters + carriers');

  // ---------- customers ----------
  const clients = [];
  for (let i = 0; i < CUSTOMERS.length; i++) {
    const [legalName, br] = CUSTOMERS[i];
    const pin = pick(ORIGINS[br]);
    const slug = legalName.toLowerCase().replace(/[^a-z]+/g, '').slice(0, 14);
    const sales = pick(SALES);
    const c = await prisma.b2bClient.create({
      data: {
        legalName, accountCode: String(500101 + i), branch: br, serviceCentre: br,
        gstin: `${STATE_CODE[br]}AAB${String.fromCharCode(65 + (i % 26))}C${String(1000 + i * 37).slice(0, 4)}D1Z${i % 9}`,
        addressLine: `${int(1, 220)}, ${pick(STREETS)}`, city: CITY[br][0], state: CITY[br][1], pincode: pin,
        contactName: `${pick(FIRST)} ${pick(LAST)}`, contactPhone: `9${digits(9)}`, contactEmail: `accounts@${slug}.example`,
        creditLimit: int(2, 10) * 100000, creditDays: pick([15, 30, 45]), canViewInvoices: true, canCheckRates: true,
        salesPerson: sales[1], csPerson: `${pick(FIRST)} ${pick(LAST)}`, startDate: new Date('2026-04-01'),
        defaultVendor: rnd() < 0.5 ? pick(CARRIERS).code : null,
      },
    });
    clients.push(c);
  }
  log('customers', clients.length);

  // ---------- users ----------
  const hash = await bcrypt.hash(PASSWORD, 10);
  const staff = [
    ['Demo Admin', 'admin@northwind.example', 'SYS_ADMIN', 'MANAGEMENT', 'ADMIN'],
    ['Vikram Ops', 'ops@northwind.example', 'HUB_MANAGER', 'OPERATIONS', 'OPS'],
    ['Sana CS', 'cs@northwind.example', 'HUB_MANAGER', 'CUSTOMER_SERVICE', 'CS'],
    ['Farhan Finance', 'finance@northwind.example', 'FINANCE_EXEC', 'FINANCE', 'FINANCE'],
    ['Ananya Kapoor', 'sales@northwind.example', 'SALES', 'SALES', 'SALES'],
  ];
  const users = {};
  for (const [fullName, email, role, department, username] of staff) users[username] = await prisma.user.create({ data: { fullName, email, username, passwordHash: hash, role, department } });
  await prisma.user.create({ data: { fullName: 'Saffron Trail (customer)', email: 'portal@saffrontrail.example', username: clients[0].accountCode, passwordHash: hash, role: 'CLIENT_ADMIN', clientId: clients[0].id } });
  const pinHash = await bcrypt.hash('1234', 10);
  const riders = [];
  for (let i = 0; i < 4; i++) riders.push(await prisma.user.create({ data: { fullName: `${pick(FIRST)} ${pick(LAST)}`, email: `rid10${i + 1}@rider.northwind.example`, passwordHash: hash, role: 'DRIVER', riderCode: `RID10${i + 1}`, pinHash, phone: `9${digits(9)}`, vehicleNo: `DL01AB${digits(4)}`, hubId: hubs.DEL.id } }));
  log('users');

  // ---------- pincodes in play ----------
  const pins = await prisma.pincode.findMany({ where: { surfaceZone: { not: null }, apexZone: { not: null } }, select: { pincode: true, city: true, state: true, surfaceZone: true, apexZone: true } });
  const zones = [...new Set(pins.flatMap((p) => [zoneOf(p.surfaceZone), zoneOf(p.apexZone)]).filter(Boolean))];
  const destPool = Array.from({ length: 450 }, () => pick(pins));
  log('pincodes', pins.length, 'zones', zones.join(' '));

  // ---------- rate cards (synthetic prices) ----------
  const PRODUCTS = [
    { product: 'SFC', mode: 'SURFACE', divisor: 27000, cft: 6, minKg: 20, unit: 1000, fuel: 12, slab: (t) => [['PLUSKG', 1, [7, 9, 12, 15][t]]] },
    { product: 'APEX', mode: 'AIR', divisor: 5000, cft: 0, minKg: 10, unit: 1000, fuel: 18, slab: (t) => [['PLUSKG', 1, [38, 48, 62, 75][t]]] },
    { product: 'DP', mode: 'AIR', divisor: 5000, cft: 0, minKg: 0.5, unit: 500, fuel: 20, slab: (t) => [['INITIAL', 0.5, [45, 60, 80, 95][t]], ['ADDITIONAL', 0.5, [35, 48, 62, 75][t]]] },
  ];
  for (const c of clients) {
    const k = between(0.88, 1.2);
    for (const p of PRODUCTS) {
      const card = await prisma.customerRateCard.create({
        data: {
          clientId: c.id, network: 'SELF', product: p.product, mode: p.mode, label: `${p.product} standard`, volumetricDivisor: p.divisor, cft: p.cft,
          minChargeableKg: p.minKg, addlWeightUnitG: p.unit, fuelMode: 'FLAT', fuelPct: p.fuel, fovPct: 0.1, fovMin: 100, awbCharge: 50,
          odaFlat: 500, minFreight: p.product === 'DP' ? 0 : 250, validFrom: new Date('2026-01-01'), isActive: true,
        },
      });
      const slabs = [];
      for (const o of zones) for (const d of zones) for (const [rateType, weight, rate] of p.slab(tier(o, d))) slabs.push({ rateCardId: card.id, originZone: o, zone: d, rateType, weight, rate: D(rate * k), slabOrder: rateType === 'INITIAL' ? 1 : 2 });
      for (let i = 0; i < slabs.length; i += 2000) await prisma.customerRateCardSlab.createMany({ data: slabs.slice(i, i + 2000) });
    }
  }
  log('rate cards');

  // ---------- carrier coverage (fictional networks) ----------
  for (const c of CARRIERS) {
    for (const [mode] of c.nets) {
      const rows = pins.map((p) => ({ pincode: p.pincode, city: p.city, state: p.state, network: c.code, mode, tatDays: int(1, 5), isOda: rnd() < 0.07, isActive: rnd() > 0.02 }));
      for (let i = 0; i < rows.length; i += 5000) await prisma.serviceablePincode.createMany({ data: rows.slice(i, i + 5000), skipDuplicates: true });
    }
  }
  log('carrier coverage');

  // ---------- shipments ----------
  const now = Date.now();
  const start = new Date('2026-09-01T03:30:00Z').getTime();
  const days = Math.floor((now - start) / DAY);
  let made = 0;
  for (let d = 0; d <= days; d++) {
    const dayStart = start + d * DAY;
    const dow = new Date(dayStart + 330 * 60000).getUTCDay();
    const n = dow === 0 ? int(3, 8) : int(16, 32);
    for (let j = 0; j < n; j++) {
      const c = pick(clients);
      const prod = rnd() < 0.55 ? 'SFC' : rnd() < 0.6 ? 'DP' : 'APEX';
      const dest = pick(destPool);
      const boxes = prod === 'DP' ? int(1, 2) : int(1, 8);
      const kg = prod === 'DP' ? D(between(0.4, 4)) : D(between(8, 160));
      const carrier = rnd() < 0.72 ? pick(CARRIERS.filter((x) => prod === 'SFC' || x.modes.includes('AIR'))) : null;
      const value = int(2, 90) * 1000;
      const L = int(20, 60), W = int(15, 45), H = int(10, 40);
      try {
        const s = await shipmentsSvc.create({
          clientId: Number(c.id), product: prod, docType: rnd() < 0.08 ? 'DOX' : 'NDOX', serviceMode: prod === 'SFC' ? 'ROAD_PTL' : 'AIR_EXPRESS',
          originZone: '', destZone: '', originPincode: c.pincode, destPincode: dest.pincode,
          shipperName: c.legalName, shipperAddress1: c.addressLine, shipperCity: c.city, shipperPincode: c.pincode, shipperMobile: c.contactPhone,
          consigneeName: `${pick(FIRST)} ${pick(LAST)}`, consigneePhone: `9${digits(9)}`, consigneeAddress: `${int(1, 400)}, ${pick(STREETS)}, ${dest.city}`,
          vendor: carrier ? carrier.code : undefined, referenceNo: `PO-${digits(6)}`, invoiceNo: `INV-${digits(5)}`, goodsDesc: pick(GOODS),
          declaredValue: value, shipmentValue: value, paymentTerm: rnd() < 0.08 ? 'TO_PAY' : 'PREPAID',
          pieces: Array.from({ length: boxes }, () => ({ deadKg: D(kg / boxes), lengthCm: L, widthCm: W, heightCm: H })),
        }, { skipAutoDispatch: true, createdById: pick([users.OPS.id, users.CS.id, riders[0].id, riders[1].id]) });
        await settle(prisma, s.awb, dayStart + between(0, 9 * 3600e3), carrier, now, riders);
        made++;
      } catch (e) { if (made < 3) console.error('book failed:', e.message); }
    }
    if (d % 7 === 0) log('shipments so far', made);
  }
  log('shipments', made);

  // ---------- pickups ----------
  for (let i = 0; i < 45; i++) {
    const c = pick(clients);
    const age = int(0, 12);
    const status = age === 0 ? pick(['REQUESTED', 'ASSIGNED']) : age < 2 ? pick(['ASSIGNED', 'PICKED']) : pick(['PICKED', 'PICKED', 'PICKED', 'CANCELLED']);
    const carrier = rnd() < 0.7 ? pick(CARRIERS) : null;
    await prisma.pickupRequest.create({
      data: {
        clientId: c.id, pickupAddress: `${c.addressLine}, ${c.city}`, city: c.city, pincode: c.pincode, contactName: c.contactName, contactPhone: c.contactPhone,
        estPieces: int(1, 12), product: pick(['SFC', 'DP', 'APEX']), weight: int(2, 300), vendor: carrier?.code ?? null, status,
        token: carrier && status !== 'REQUESTED' ? digits(8) : null, handoffAt: carrier && status !== 'REQUESTED' ? new Date(now - age * DAY) : null,
        assignedRiderId: status === 'ASSIGNED' || status === 'PICKED' ? pick(riders).id : null, createdAt: new Date(now - age * DAY - int(1, 8) * 3600e3),
        createdByName: pick(['Sana CS', 'Vikram Ops', 'Saffron Trail (customer)']), refNo: `PU-${digits(5)}`,
      },
    });
  }
  log('pickups');

  // ---------- invoices (real billing engine) ----------
  const periods = [['2026-09-01', '2026-09-30', 'paid'], ['2026-10-01', '2026-10-31', 'mixed']];
  for (const [ps, pe, kind] of periods) {
    for (const c of clients) {
      try {
        const inv = await invoices.generate(Number(c.id), ps, `${pe}T23:59:59.999+05:30`);
        const id = Number(inv.id);
        if (kind === 'mixed' && rnd() < 0.25) continue; // a few left as drafts for the demo
        await invoices.lockInvoice(id);
        await invoices.send(id);
        const total = Number(inv.total);
        const r = rnd();
        if (kind === 'paid' && r < 0.85) await invoices.pay(id, D(total * 0.98), D(total * 0.02), 0, undefined, `UTR${digits(10)}`);
        else if (kind === 'mixed' && r < 0.35) await invoices.pay(id, D(total * 0.5), 0, 0, undefined, `UTR${digits(10)}`);
      } catch (e) { /* nothing billable this period */ }
    }
  }
  log('invoices');

  // ---------- vendor cost lines (for P&L) ----------
  const forwarded = await prisma.shipment.findMany({ where: { vendor: { in: CARRIERS.map((c) => c.code) }, createdAt: { lt: new Date('2026-10-25') } }, include: { invoiceLines: { select: { amount: true }, take: 1 } } });
  const vb = forwarded.filter((s) => s.invoiceLines[0]).map((s) => {
    const sell = Number(s.invoiceLines[0].amount); const cost = D(sell * between(0.62, 0.86));
    return { vendorCode: s.vendor, awb: s.forwardingAwb || s.awb, forwardingNo: s.forwardingAwb, product: s.product, pickupDate: s.createdAt, origin: s.originZone, destination: s.destZone, actWeight: Number(s.totalDeadKg), chrgWeight: Number(s.chargeWeight ?? s.totalDeadKg), pcs: s.pieceCount, freight: D(cost * 0.8), fs: D(cost * 0.15), awbCharge: D(cost * 0.05), total: cost, totalWithGst: D(cost * 1.18), destPincode: s.destPincode };
  });
  for (let i = 0; i < vb.length; i += 500) await vendorBills.bulkUpsert(vb.slice(i, i + 500));
  log('vendor cost lines', vb.length);

  // ---------- vendor bill register + payments ----------
  for (const c of CARRIERS) {
    for (const [m, from, to, due] of [['09', '2026-09-01', '2026-09-30', '2026-10-20'], ['10', '2026-10-01', '2026-10-31', '2026-11-20']]) {
      const amt = int(80, 420) * 1000;
      const inv = await vendorBills.createInvoice({ vendorCode: c.code, periodFrom: from, periodTo: to, invoiceDate: m === '09' ? '2026-10-05' : '2026-11-01', location: pick(['Delhi', 'Mumbai']), invoiceNo: `${c.code}/${m}/${digits(4)}`, amount: amt, gst: D(amt * 0.18), dueDate: due });
      if (m === '09') await vendorBills.recordPayment({ invoiceIds: [inv.id], paidOn: '2026-10-18', amount: D(amt * 1.18 * 0.98), tds: D(amt * 0.02), mode: 'NEFT', reference: `UTR${digits(10)}` });
    }
  }
  log('vendor register');

  // ---------- expenses + attendance ----------
  for (let i = 0; i < 40; i++) {
    await prisma.expense.create({ data: { date: new Date(now - int(0, 55) * DAY), mode: pick(['CASH', 'UPI', 'A/C TRANSFER', 'CARD']), category: pick(['Vehicle', 'Office', 'Stationary', 'Internet', 'Staff welfare', 'Freight']), remark: pick(['Fuel', 'Tea & snacks', 'Printer cartridge', 'Broadband bill', 'Tempo hire', 'Packing tape']), amount: int(150, 6500), branch: pick(['DEL', 'BOM', 'BLR']), paidBy: pick(FIRST), createdById: users.OPS.id } });
  }
  const people = [...Object.values(users), ...riders];
  for (let d = 1; d <= 20; d++) {
    const day = new Date(now - d * DAY); const dow = new Date(+day + 330 * 60000).getUTCDay(); if (dow === 0) continue;
    const base = Date.UTC(day.getUTCFullYear(), day.getUTCMonth(), day.getUTCDate()) - 330 * 60000;
    for (const u of people) {
      if (rnd() < 0.08) continue;
      await prisma.loginLog.create({ data: { userId: u.id, kind: 'IN', at: new Date(base + (9 + between(0, 1.2)) * 3600e3), via: u.role === 'DRIVER' ? 'app' : 'web' } });
      if (rnd() < 0.85) await prisma.loginLog.create({ data: { userId: u.id, kind: 'OUT', at: new Date(base + (18 + between(0, 1.5)) * 3600e3), via: u.role === 'DRIVER' ? 'app' : 'web' } });
    }
  }
  log('expenses + attendance');
  console.log(`\nDemo ready. Staff logins (password ${PASSWORD}): admin@ / ops@ / cs@ / finance@ / sales@northwind.example · customer: username ${clients[0].accountCode} · riders RID101–RID104 PIN 1234`);
  await app.close();
  process.exit(0);
})().catch((e) => { console.error(e); process.exit(1); });

/** Back-date a fresh booking and walk it through a realistic life: scans, carrier no, POD, status. */
async function settle(prisma, awb, bookedAt, carrier, now, riders) {
  const ageDays = (now - bookedAt) / DAY;
  const tat = int(2, 5);
  const r = rnd();
  let path;
  if (ageDays < 0.4) path = r < 0.6 ? ['MAN'] : ['MAN', 'PKD'];
  else if (ageDays < 2) path = r < 0.3 ? ['MAN', 'PKD'] : r < 0.75 ? ['MAN', 'PKD', 'DPD'] : ['MAN', 'PKD', 'DPD', 'DRD'];
  else if (ageDays < tat + 1) path = r < 0.25 ? ['MAN', 'PKD', 'DPD', 'DRD'] : r < 0.45 ? ['MAN', 'PKD', 'DPD', 'DRD', 'OFD'] : r < 0.9 ? ['MAN', 'PKD', 'DPD', 'DRD', 'OFD', 'DLD'] : ['MAN', 'PKD', 'DPD', 'DRD', 'OFD', 'UDL'];
  else path = r < 0.86 ? ['MAN', 'PKD', 'DPD', 'DRD', 'OFD', 'DLD'] : r < 0.9 ? ['MAN', 'PKD', 'DPD', 'DRD', 'OFD', 'UDL', 'RTO'] : r < 0.93 ? ['MAN', 'PKD', 'DPD', 'DRD', 'OFD', 'UDL', 'RTO', 'RTD'] : r < 0.95 ? ['MAN', 'CAN'] : r < 0.98 ? ['MAN', 'PKD', 'DPD', 'DRD', 'OFD', 'UDL'] : ['MAN', 'PKD', 'DPD', 'DRD'];
  const offs = { MAN: 0, PKD: 0.2, DPD: 0.6, DRD: Math.max(1.2, tat - 1), OFD: tat - 0.3, DLD: tat - 0.1, UDL: tat - 0.1, RTO: tat + 1, RTD: tat + 4, CAN: 0.1 };
  const at = (c) => new Date(Math.min(now - 60e3, bookedAt + offs[c] * DAY + between(0, 3) * 3600e3));
  const last = path[path.length - 1];
  const STATUS = { MAN: 'CREATED', PKD: 'PICKED_UP', DPD: 'IN_TRANSIT', DRD: 'AT_HUB', OFD: 'OUT_FOR_DELIVERY', DLD: 'DELIVERED', UDL: 'EXCEPTION', RTO: 'EXCEPTION', RTD: 'DELIVERED', CAN: 'CANCELLED' };
  const LOC = { MAN: 'Booking desk', PKD: 'Origin hub', DPD: 'Origin hub', DRD: 'Destination hub', OFD: 'Destination hub', DLD: 'Consignee address', UDL: 'Consignee address', RTO: 'Destination hub', RTD: 'Origin hub', CAN: 'Booking desk' };
  const UDL_WHY = ['Consignee not available', 'Address incomplete', 'Consignee refused', 'Premises closed'];
  const s = await prisma.shipment.findUnique({ where: { awb }, select: { id: true, pieceCount: true, consigneeName: true } });
  const delivered = last === 'DLD';
  await prisma.shipment.update({
    where: { awb },
    data: {
      createdAt: new Date(bookedAt), statusCode: last, status: STATUS[last], statusAt: at(last), currentLocation: LOC[last],
      expectedDelivery: new Date(bookedAt + tat * DAY),
      ...(carrier && last !== 'CAN' && path.includes('PKD') ? { forwardingAwb: `${carrier.code === 'SKY' ? '5' : carrier.code === 'RDW' ? '3' : '9'}${digits(10)}`, forwardingAt: at('PKD'), bdStatus: `${last === 'DLD' ? 'Delivered' : last === 'OFD' ? 'Out for delivery' : last === 'UDL' ? 'Undelivered' : 'In transit'} (${carrier.name})` } : {}),
      ...(delivered ? { podReceivedBy: rnd() < 0.7 ? s.consigneeName : `${pick(FIRST)} (security)`, deliveryRiderId: carrier ? null : pick(riders).id } : {}),
      ...(last === 'UDL' ? { exceptionFlag: pick(UDL_WHY) } : {}),
    },
  });
  await prisma.shipmentPiece.updateMany({ where: { shipmentId: s.id }, data: { status: delivered ? 'DELIVERED' : last === 'OFD' ? 'OUT_FOR_DELIVERY' : ['DPD', 'DRD'].includes(last) ? 'IN_TRANSIT' : last === 'PKD' ? 'PICKED_UP' : 'CREATED' } });
  await prisma.scanLog.createMany({ data: path.map((c) => ({ awb, eventType: c, scanAt: at(c), serviceCenter: LOC[c], remark: c === 'UDL' ? pick(UDL_WHY) : c === 'DLD' ? 'Delivered' : null })) });
}
